['settings','Settings','Account & states','Account, units, notifications, privacy, and data controls.'],['account','Your account','Account & states','Basic account details and deliberate account deletion.'],['notification-settings','Notification settings','Account & states','Separate necessary care reminders from optional updates.'],['privacy','Privacy & ads','Account & states','Manage ad choices and shared-data access; preferences can be changed later.'],['premium','Pet care Plus','Account & states','An optional ad-free plan that preserves all essential care features for free users.'],['help','Help & support','Account & states','Searchable practical help with a support entry point.'],['empty','No pets yet','Account & states','A warm empty state with a single contextual action.'],['offline','You’re offline','Account & states','Show what remains available and make sync status explicit.'],['error','Upload interrupted','Account & states','Recoverable failure with retry and preservation of form context.'],['delete','Delete account','Account & states','A deliberate, typed confirmation for an irreversible account action.']
