const screens=screenDefs.map(([id,title,group,note])=>({id,title,group,note}));const groups=[...new Set(screens.map(s=>s.group))];
let current='home',view='prototype',galleryGroup='All',pet='milo',taskFilter='All',dateSelected=9,mood='Happy',walkSeconds=0,walkRunning=false,walkInterval=null;
let state; function resetState(){state={tasks:[{id:1,title:'Morning meal',sub:'8:00 AM · Emma',type:'food',done:true},{id:2,title:'Morning walk',sub:'9:00 AM · Alex',type:'walk',done:true},{id:3,title:'Fresh water',sub:'11:00 AM · Emma',type:'heart',done:true},{id:4,title:'Evening walk',sub:'5:30 PM · Alex',type:'walk',done:false},{id:5,title:'Evening meal',sub:'6:00 PM · Emma',type:'food',done:false}],history:[],weights:[],expenses:[],expenseCurrency:'GBP (£)',reminders:[],vaccine:null,medication:null,record:null,visit:null,invite:null,handoff:null,petName:'Milo',catName:'Luna',newPet:false,savedArticle:false,consent:false,essential:true,uploadedName:null,petPhoto:null,taskOpen:4,selectedAmount:'120',deleted:false}}resetState();
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function petName(){return pet==='luna'?state.catName:state.petName}function photo(p=pet,cls=''){return `<img class="avatar ${cls}" src="${p==='milo'&&state.petPhoto?state.petPhoto:'assets/'+p+'.webp'}" alt="${p==='milo'?escapeHtml(state.petName):escapeHtml(state.catName)}">`}
function go(id){if(!screens.some(s=>s.id===id))return;document.getElementById('demo-dialog')?.close();current=id;view='prototype';location.hash=id;render()}
function btn(text,to,kind='primary'){return `<button class="${kind}" data-go="${to}">${text}</button>`}function action(text,a,kind='primary'){return `<button class="${kind}" data-action="${a}">${text}</button>`}
function back(title,to='home',right=''){return `<div class="back-header"><button class="icon-btn" data-go="${to}" aria-label="Back">${icon('back')}</button><b>${title}</b>${right||'<span style="width:32px"></span>'}</div>`}
function heading(title,sub='',right='notifications',rightIcon='bell'){return `<div class="mobile-header"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon-btn" data-go="${right}" aria-label="${right==='notifications'?'Notifications':'Open '+right}">${icon(rightIcon)}</button></div>`}
function section(title,to='',label='See all'){return `<div class="section-head"><h3>${title}</h3>${to?`<button data-go="${to}">${label}</button>`:''}</div>`}
function petChips(){return `<div class="pet-switch"><button data-pet="milo" class="pet-chip ${pet==='milo'?'active':''}">${photo('milo')}${escapeHtml(state.petName)}</button><button data-pet="luna" class="pet-chip ${pet==='luna'?'active':''}">${photo('luna')}${escapeHtml(state.catName)}</button><button data-go="add-pet" class="pet-chip" aria-label="Add pet">${icon('plus')}</button></div>`}
function nav(active){return `<nav class="bottom-nav" aria-label="App navigation">${[['home','home','Today'],['pets','pet','Pets'],['log','plus','Log'],['circle','users','Circle'],['more','more','More']].map(([id,i,t])=>`<button data-go="${id}" class="${id===active?'active':''} ${id==='log'?'add-nav':''}" aria-label="${t}">${icon(i)}${id==='log'?'':t}</button>`).join('')}</nav>`}
function shell(content,active='',footer=''){return `<div class="mobile-screen"><div class="mobile-scroll">${content}</div>${footer?`<div class="sticky-action">${footer}</div>`:active?nav(active):''}</div>`}
function field(label,name,type='text',value='',placeholder='',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${escapeHtml(value)}" placeholder="${escapeHtml(placeholder)}" ${extra}></label>`}
function select(label,name,options){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(s=>`<option>${s}</option>`).join('')}</select></label>`}
function textarea(label,name,placeholder='',value=''){return `<label class="field"><span>${label}</span><textarea name="${name}" placeholder="${escapeHtml(placeholder)}">${escapeHtml(value)}</textarea></label>`}
function form(id,contents,label='Save',to='home'){return `<form data-form="${id}" data-next="${to}">${contents}<button class="primary" type="submit">${label}</button></form>`}
function toggle(label,desc,name,checked=true){return `<div class="toggle-row"><div class="grow"><b>${label}</b>${desc?`<p>${desc}</p>`:''}</div><label class="toggle"><input type="checkbox" name="${name}" aria-label="${label}" ${checked?'checked':''}><span></span></label></div>`}
function listRow(title,sub,i,to,color=''){return `<button class="list-button" data-go="${to}"><span class="icon-tile ${color}">${icon(i)}</span><span class="grow"><b>${title}</b>${sub?`<small>${sub}</small>`:''}</span><span class="chevron">›</span></button>`}
function taskRows(){const rows=state.tasks.filter(t=>taskFilter==='Done'?t.done:taskFilter==='To do'?!t.done:true);return rows.length?rows.map(t=>`<div class="task-row ${t.done?'completed':''}"><span class="icon-tile ${t.type==='food'?'orange':''}">${icon(t.type)}</span><button class="task-info" data-task="${t.id}"><strong>${t.title}</strong><small>${t.sub}</small></button><button class="check-btn ${t.done?'done':''}" data-complete="${t.id}" aria-label="${t.done?'Undo':'Complete'} ${t.title}">${t.done?icon('check'):''}</button></div>`).join(''):'<div class="card center"><p>Nothing here yet. Your completed care will appear here.</p></div>'}
function ad(){return `<div class="ads"><div class="ads-label"><span>SPONSORED · SAMPLE PLACEMENT</span><span>Ad</span></div><div class="row"><span class="icon-tile orange">${icon('pet')}</span><div class="grow"><h4>Good days start with play.</h4><p>Explore everyday enrichment.</p></div><button data-action="ad-demo">Learn more</button></div></div>`}
function info(label,value){return `<div><p class="info-label">${label}</p><p class="info-value">${escapeHtml(value)}</p></div>`}
function progress(n){return `<div class="step-label">STEP ${n} OF 3</div><div class="step-progress">${[1,2,3].map(i=>`<span class="${i<=n?'current':''}"></span>`).join('')}</div>`}
function onboard(id){let data={welcome:['Little moments.<br><span>Big love.</span>','The easy way to keep your pet happy, cared for, and part of the family.','Let’s get started','intro-care',0], 'intro-care':['Every day,<br><span>taken care of.</span>','Meals, walks, medications. Build a rhythm that works for your pet and your life.','Continue','intro-family',1], 'intro-family':['Their people.<br><span>One care circle.</span>','No more “Did someone feed Milo?” Share the routine and see every little update.','Continue','intro-health',2], 'intro-health':['Their whole story.<br><span>Always with you.</span>','Keep records together and leave a thoughtful care guide when someone else takes over.','Create my account','signup',3]}[id];return shell(`<div class="onboard"><div class="onboard-brand"><span class="mobile-logo">Pet care</span><button class="text-btn" data-go="home">Explore demo</button></div><img class="onboard-art" src="assets/cozy-friends.webp" alt="A playful golden retriever and gray cat sitting together"><h1>${data[0]}</h1><p>${data[1]}</p><div class="pager">${[0,1,2,3].map(i=>`<span class="${i===data[4]?'active':''}"></span>`).join('')}</div></div>`,'',`<div class="button-stack">${btn(data[2],data[3])}<button class="text-btn" data-go="signin">Already have an account? Sign in</button></div>`)}
function screen(id){if(id.startsWith('intro-')||id==='welcome')return onboard(id);
const name=escapeHtml(petName());
switch(id){
case 'signup':return shell(`${back('','welcome')}<div class="mobile-logo">Pet care</div><h1 class="form-title" style="margin-top:28px">Your pet’s people.<br>All together.</h1><p class="form-description">Create your free care account.</p>${form('signup',field('Your name','name','text','','Emma', 'required autocomplete="name"')+field('Email address','email','email','','emma@example.com','required autocomplete="email"')+field('Password','password','password','','At least 8 characters','required minlength="8" autocomplete="new-password"')+'<label class="check-field"><input type="checkbox" required> <span>I agree to the <button type="button" class="text-btn small" data-go="privacy">Terms & Privacy</button>.</span></label>','Create account','consent')}<div class="divider">or continue with</div><div class="two-cols">${action('Apple','social-apple','secondary')}${action('Google','social-google','secondary')}</div><p class="center small muted">Already here? <button class="text-btn small" data-go="signin">Sign in</button></p>`);
case 'signin':return shell(`${back('','welcome')}<img class="center-art" style="width:120px;height:120px" src="assets/cozy-friends.webp" alt="Dog and cat"><h1 class="form-title">Good to see you.</h1><p class="form-description">Let’s check in on your little ones.</p>${form('signin',field('Email address','email','email','','emma@example.com','required autocomplete="email"')+field('Password','password','password','','Your password','required autocomplete="current-password"')+'<div style="text-align:right;margin:-4px 0 20px"><button type="button" class="text-btn small" data-go="forgot">Forgot password?</button></div>','Sign in','home')}<div class="divider">or continue with</div><div class="two-cols">${action('Apple','social-apple','secondary')}${action('Google','social-google','secondary')}</div><p class="center small muted">New to Pet care? <button class="text-btn small" data-go="signup">Create account</button></p>`);
case 'forgot':return shell(`${back('Reset password','signin')}<div class="big-icon">${icon('lock')}</div><h1 class="form-title">Let’s get you<br>back in.</h1><p class="form-description">Enter your email and we’ll help you reset your password.</p>${form('forgot',field('Email address','email','email','','emma@example.com','required'),'Send reset link','reset-sent')}`);
case 'reset-sent':return shell(`${back('','signin')}<div class="center success"><div class="big-icon">${icon('mail')}</div><h1 class="form-title">Check your inbox.</h1><p class="form-description">If there’s an account linked to that email, you’ll receive a reset link.</p><div class="card"><p class="small muted">In this design prototype, no email is sent.</p></div></div>`,'',`${btn('Back to sign in','signin')}`);
case 'consent':return shell(`${back('Your choices','signup')}<div class="big-icon">${icon('shield')}</div><h1 class="form-title">A little clarity<br>about ads.</h1><p class="form-description">Ads help keep everyday care free. You choose whether ads use your interests.</p><div class="card">${listRow('Personalized ads','Use ad-related data for relevant ads.','heart','privacy')}${listRow('Manage choices','Review each preference at any time.','settings','privacy')}</div><p class="small muted" style="line-height:1.8">Your pet’s health notes and documents are never used to personalize ads. Essential care and emergency information stay ad-free.</p>`,'',`<div class="button-stack">${action('Allow personalized ads','allow-ads')}${action('Continue without personalization','decline-ads','secondary')}<button class="text-btn" data-go="privacy">Manage preferences</button></div>`);
case 'permissions':return shell(`${back('Stay on track','consent')}<img class="center-art" src="assets/milo.webp" alt="Friendly golden retriever"><h1 class="form-title">The little things<br>are easy to miss.</h1><p class="form-description">Get gentle reminders for meals, walks, appointments, and prescribed medication.</p><div class="card row"><span class="icon-tile">${icon('bell')}</span><div><h4>Evening walk · 5:30 PM</h4><p>Milo’s ready for a little adventure.</p></div></div><p class="small muted">You can change notification preferences anytime.</p>`,'',`<div class="button-stack">${action('Enable reminders','enable-reminders')}<button class="text-btn" data-go="add-pet">Maybe later</button></div>`);
case 'add-pet':return shell(`${back('A new little friend','pets')}${progress(1)}<h1 class="form-title">Who’s joining<br>the family?</h1><p class="form-description">Let’s make a home for their care.</p><button class="upload-zone" data-action="upload-photo">${icon('camera')}<b>${state.petPhoto?'Photo added':'Add a pet photo'}</b><small>Camera or photo library</small></button>${form('add-pet',field('Pet’s name','petName','text','','e.g. Milo','required maxlength="40"')+select('They’re a…','species',['Dog','Cat','Rabbit','Bird','Other']),'Continue','pet-details')}`);
case 'pet-details':return shell(`${back('A few little details','add-pet')}${progress(2)}<h1 class="form-title">Every pet<br>has a story.</h1><p class="form-description">Add what you know. You can fill in the rest later.</p>${form('pet-details',field('Breed','breed','text','','Golden retriever')+field('Birthday (optional)','birthday','date','2023-04-12')+'<div class="two-cols">'+select('Sex','sex',['Male','Female','Unknown'])+field('Weight (kg)','weight','number','','28.4','step="0.1" min="0.1"')+'</div>'+select('Spayed / neutered','neutered',['Yes','No','Unknown']),'Continue','routine-setup')}<button class="text-btn" style="width:100%;margin-top:10px" data-go="routine-setup">Skip for now</button>`);
case 'routine-setup':return shell(`${back('Their everyday rhythm','pet-details')}${progress(3)}<h1 class="form-title">Small habits.<br>Happy days.</h1><p class="form-description">Choose a starter routine. Adjust it whenever life changes.</p>${form('routine',toggle('Meals','Morning and evening','meals')+toggle('Walks','Morning and evening','walks')+toggle('Fresh water','A midday check','water')+field('Morning meal','morning','time','08:00')+field('Evening meal','evening','time','18:00'),'Create routine','ready')}`);
case 'ready':return shell(`<div class="center success"><img class="center-art" style="width:250px;height:250px;margin-top:35px" src="assets/cozy-friends.webp" alt="Happy dog and cat"><span class="tag green">${icon('check')} ALL SET</span><h1 class="form-title" style="margin-top:22px">Here’s to more<br>good days.</h1><p class="form-description">${name}’s care home is ready.<br>You’re doing great already.</p></div>`,'',`<div class="button-stack">${btn('Take me to today','home')}${btn('Invite a caregiver','invite','secondary')}</div>`);
case 'home':{let done=state.tasks.filter(t=>t.done).length;return shell(`${heading('Good morning, Emma','Friday, October 9')}${petChips()}<div class="hero-card narrow"><span class="tag">${name}’S DAY</span><h2>A good day<br>in the making.</h2><p>${state.tasks.length-done} little things left to do.</p><div class="ring" style="background:conic-gradient(var(--orange) 0 ${done/Math.max(1,state.tasks.length)*360}deg,#ffffff20 0)"><div><strong>${done}/${state.tasks.length}</strong><small>care tasks</small></div></div></div>${section('A little check-in')}<div class="quick-grid">${[['food','Meal','feeding','orange'],['walk','Walk','walk',''],['pill','Medicine','medications','green'],['heart','Wellbeing','wellbeing','pink']].map(([i,t,to,c])=>`<button class="quick-action" data-go="${to}"><span class="icon-tile ${c}">${icon(i)}</span>${t}</button>`).join('')}</div>${section('Up next','schedule','Full day')}${state.tasks.filter(t=>!t.done).map(t=>`<div class="task-row"><span class="icon-tile ${t.type==='food'?'orange':''}">${icon(t.type)}</span><button class="task-info" data-task="${t.id}"><strong>${t.title}</strong><small>${t.sub}</small></button><button class="check-btn" data-complete="${t.id}" aria-label="Complete ${t.title}"></button></div>`).join('')||'<div class="card row"><span class="icon-tile green">'+icon('check')+'</span><div><h4>All cared for.</h4><p>Everything is done for today.</p></div></div>'}<button class="banner" style="width:100%;text-align:left" data-go="circle"><span class="icon-tile orange">${icon('users')}</span><span><b>Care is better together.</b><p>Alex logged a morning walk at 9:18 AM.</p></span></button>${section('Recently logged','history')}${timeline()}`,'home')}
case 'schedule':return shell(`${heading('Care calendar','A little rhythm for every day.','add-reminder','plus')}${petChips()}<div class="section-head"><h3>October 2026</h3><button data-action="calendar-demo">This week</button></div><div class="date-strip">${['M','T','W','T','F','S','S'].map((d,i)=>`<button class="date-button ${dateSelected===i+5?'active':''}" data-date="${i+5}">${d}<b>${i+5}</b></button>`).join('')}</div><div class="segmented">${['All','To do','Done'].map(x=>`<button data-filter="${x}" class="${taskFilter===x?'active':''}">${x}</button>`).join('')}</div><p class="small muted">${dateSelected===9?'Today':`Friday routine preview · October ${dateSelected}`} · ${state.tasks.filter(t=>t.done).length} of ${state.tasks.length} complete</p>${taskRows()}${btn('Add a care reminder','add-reminder','secondary')}`,'home');
case 'task':{let t=state.tasks.find(t=>t.id===state.taskOpen)||state.tasks[3]||{id:4,title:'Evening walk',sub:'5:30 PM · Alex',type:'walk',done:false};return shell(`${back('Care task','schedule')}<div class="center"><div class="big-icon">${icon(t.type)}</div><span class="tag ${t.done?'green':'orange'}">${t.done?'COMPLETED':'UP NEXT'}</span><h1 class="form-title" style="margin-top:18px">${t.title}</h1><p class="form-description">For ${name}</p></div><div class="card"><div class="detail-grid">${info('Scheduled',t.sub.split(' · ')[0])}${info('Assigned to',t.sub.split(' · ')[1])}${info('Repeat','Every day')}${info('Last completed',t.done?'Today':'Yesterday')}</div></div>${section('A little reminder')}<div class="card"><p class="small muted" style="line-height:1.8">${t.type==='walk'?'Milo loves the park route. Take the blue harness and a water bottle.':t.type==='food'?'Use the usual bowl. Fresh water is on the kitchen counter.':'Rinse the bowl and refill it with fresh water.'}</p></div>${listRow('Edit reminder','Timing, repeat, and caregiver','edit','add-reminder')}`,'',action(t.done?'Undo completion':'Mark as done','task-done'))}
case 'log':return shell(`${back('A little moment of care','home')}<h1 class="form-title">What did you<br>do together?</h1><p class="form-description">Every little thing counts.</p>${petChips()}<div class="card list-card">${listRow('Meal','Food and fresh water','food','feeding','orange')}${listRow('Walk','Time outside together','walk','walk')}${listRow('Medication','Log a prescribed dose','pill','medications','green')}${listRow('Wellbeing','Mood and observations','heart','wellbeing','pink')}${listRow('Weight','A new measurement','weight','add-weight')}${listRow('Something else','Add a custom care note','edit','wellbeing')}</div>`,'log');
case 'feeding':return shell(`${back('Log a meal','log')}${petChips()}<h1 class="form-title">A happy little<br>mealtime.</h1>${form('feeding',select('Meal','meal',['Breakfast','Lunch','Dinner','Snack'])+field('Food','food','text','Dry food','','required')+'<div class="two-cols">'+field('Amount','amount','number','120','','required min="0.1" step="0.1"')+select('Unit','unit',['g','oz','cups'])+'</div>'+field('Time','time','time','08:00','', 'required')+textarea('Notes (optional)','notes','How did they eat?'),'Log meal','care-saved')}`);
case 'walk':return shell(`${back('Walk together','log')}${petChips()}<div class="walk-visual">${icon('walk')}<h3>A little adventure.</h3><p class="small muted">Enjoy the world together.</p></div><div class="timer" id="walk-timer">${timeString(walkSeconds)}</div><p class="center small muted">${walkRunning?'Timer is running':'Ready when you are'}</p><div class="two-cols" style="margin:28px 0">${action(walkRunning?'Pause':'Start walk','timer-toggle',walkRunning?'secondary':'primary')}${btn('Finish walk','walk-summary','secondary')}</div><div class="banner"><span class="icon-tile orange">${icon('shield')}</span><div><b>Just you and your pet.</b><p>This timer doesn’t collect location data.</p></div></div><button class="text-btn" style="width:100%" data-go="walk-summary">Add a walk manually</button>`);
case 'walk-summary':return shell(`${back('Walk summary','walk')}<div class="center"><div class="big-icon">${icon('walk')}</div><h1 class="form-title">A little fresh air.</h1><p class="form-description">Add this walk to ${name}’s day.</p></div>${form('walk-summary',field('Duration (minutes)','duration','number',Math.max(1,Math.round(walkSeconds/60)),'','required min="1" max="1440"')+field('When','time','time','09:00','', 'required')+textarea('Notes (optional)','notes','e.g. Park loop, lots of sniffing'),'Save walk','care-saved')}`);
case 'wellbeing':return shell(`${back('Wellbeing check-in','log')}${petChips()}<h1 class="form-title">How’s ${name}<br>feeling today?</h1><p class="form-description">Keep a note of what you notice.</p><div class="mood-row">${[['Happy','☺'],['Calm','◡'],['Tired','☾'],['Unwell','☁']].map(([t,e])=>`<button class="mood-choice ${mood===t?'active':''}" data-mood="${t}"><span>${e}</span>${t}</button>`).join('')}</div>${form('wellbeing',select('Appetite','appetite',['As usual','Less than usual','More than usual'])+select('Energy','energy',['As usual','Lower than usual','Higher than usual'])+textarea('Observations','notes','Anything you’d like to remember?'),'Save check-in','care-saved')}<p class="small muted" style="line-height:1.7">These are your observations. If something worries you, contact your vet.</p>`);
case 'history':return shell(`${heading('Care history','The little things, remembered.','insights','chart')}${petChips()}${section('Today · October 9')}${timeline(true)}${section('Yesterday · October 8')}<div class="card">${entry('food','Evening meal','6:02 PM · Emma · 120 g')}${entry('walk','Evening walk','5:32 PM · Alex · 28 min')}${entry('heart','Feeling happy','11:15 AM · Emma · Appetite as usual')}</div>`,'home');
case 'care-saved':return shell(`<div class="center success"><div class="big-icon" style="margin-top:100px">${icon('check')}</div><h1 class="form-title">A little care.<br>All logged.</h1><p class="form-description">${name}’s timeline is up to date.<br>Your care circle can see this update.</p><div class="card row">${photo()}<div><h4>${state.history[0]?escapeHtml(state.history[0].title):'Care added'}</h4><p>Logged by Emma · Just now</p></div></div></div>`,'',`<div class="button-stack">${btn('Back to today','home')}${btn('View care history','history','secondary')}</div>`);
case 'pets':return shell(`${heading('My little family','All their care, in one place.','add-pet','plus')}${['milo','luna'].map(p=>`<button class="card" data-open-pet="${p}" style="width:100%;text-align:left;color:var(--ink);padding:12px"><img class="profile-image" src="assets/${p}.webp" alt="${p==='milo'?'Golden retriever':'Gray cat'}" style="height:175px"><div class="pet-profile-head" style="padding:0 5px 8px"><div><h1 style="font-size:24px">${escapeHtml(p==='milo'?state.petName:state.catName)}</h1><p>${p==='milo'?'Golden retriever · 3 years':'British shorthair · 2 years'}</p></div><span class="tag ${p==='milo'?'orange':''}">${p==='milo'?'Dog':'Cat'}</span></div></button>`).join('')}${btn('Add a pet','add-pet','secondary')}`,'pets');
case 'profile':return shell(`${back('Pet profile','pets',`<button class="text-btn" data-go="edit-pet">Edit</button>`)}<img class="profile-image" src="assets/${pet}.webp" alt="${name}"><div class="pet-profile-head"><div><h1>${name}</h1><p>${pet==='milo'?'Golden retriever':'British shorthair'} · ${pet==='milo'?'3':'2'} years old</p></div><span class="tag orange">${pet==='milo'?'Good boy':'Good girl'}</span></div><div class="mini-stats"><div class="stat"><b>${pet==='milo'?'28.4':'4.8'}<small>kg</small></b><small>Weight</small></div><div class="stat"><b>${pet==='milo'?'Male':'Female'}</b><small>Sex</small></div><div class="stat"><b>April 12</b><small>Birthday</small></div></div><div class="card list-card">${listRow('Health passport','Their story, ready to share','shield','passport')}${listRow('Vaccinations','Records and next due dates','heart','vaccines','pink')}${listRow('Medications','Prescribed care and reminders','pill','medications','green')}${listRow('Weight trends','Follow their measurements','weight','weight')}${listRow('Health documents','Records, results, and receipts','file','records')}${listRow('Vet visits','Appointments and notes','calendar','visits','orange')}${listRow('Emergency card','Contacts when you need them','phone','emergency','pink')}</div>`,'pets');
case 'edit-pet':return shell(`${back('Edit pet','profile')}${form('edit-pet',`<div class="center">${photo(pet,'large')}<button type="button" class="text-btn" data-action="upload-photo">Change photo</button></div>`+field('Name','petName','text',petName(),'','required')+field('Breed','breed','text',pet==='milo'?'Golden retriever':'British shorthair')+field('Birthday','birthday','date','2023-04-12')+field('Microchip number','chip','text','985 141 004 123 456')+textarea('Notes','notes','','Loves the park and a good belly rub.'),'Save changes','profile')}`);
case 'passport':return shell(`${back('Health passport','profile')}<div class="passport"><div class="row">${photo(pet,'large')}<div><span class="tag">PET PASSPORT</span><h2>${name}</h2><p>${pet==='milo'?'Golden retriever':'British shorthair'}</p></div></div><div class="detail-grid">${info('Date of birth','12 Apr 2023')}${info('Weight',pet==='milo'?'28.4 kg':'4.8 kg')}${info('Microchip','985 141 004 123 456')}${info('Care contact','Emma Williams')}</div></div>${section('Important information')}<div class="card list-card">${listRow('Vaccination records','2 doses recorded','heart','vaccines')}${listRow('Medication instructions','Vet-provided care notes','pill','medications')}${listRow('Vet and emergency contacts','Parkside Veterinary Clinic','phone','vet')}${listRow('Health documents','3 documents saved','file','records')}</div><p class="small muted" style="line-height:1.7">A care summary, not an official travel certificate. Review the information before sharing.</p>`,'',action('Preview passport export','export-passport'));
case 'vaccines':return shell(`${heading('Vaccinations',name+'’s recorded care.','add-vaccine','plus')}${back('','profile')}<div class="banner"><span class="icon-tile orange">${icon('calendar')}</span><div><b>Annual booster coming up</b><p>Next due · October 22, 2026</p></div></div>${section('Recorded vaccinations')}<div class="card"><div class="row"><span class="icon-tile green">${icon('shield')}</span><div class="grow"><h4>${state.vaccine?escapeHtml(state.vaccine.name):'DHPP booster'}</h4><p>${state.vaccine?escapeHtml(state.vaccine.date):'October 22, 2025'} · Dr. Morgan</p></div><span class="tag green">Recorded</span></div></div><div class="card"><div class="row"><span class="icon-tile">${icon('shield')}</span><div class="grow"><h4>Rabies</h4><p>April 15, 2025 · Parkside Clinic</p></div></div><p class="small muted">Next due · April 15, 2028</p></div>${btn('Add a vaccination record','add-vaccine','secondary')}`);
case 'add-vaccine':return shell(`${back('Add vaccination','vaccines')}${petChips()}${form('vaccine',field('Vaccine name','name','text','','e.g. DHPP booster','required')+field('Given on','date','date','2026-10-09','','required')+field('Next due (optional)','due','date','')+field('Clinic / vet','vet','text','','Parkside Veterinary Clinic')+textarea('Notes','notes','Details from your vet'),'Save vaccination','vaccines')}`);
case 'medications':return shell(`${heading('Medications','Prescribed care, clearly recorded.','add-medication','plus')}${back('','profile')}<div class="card"><div class="row"><span class="icon-tile green">${icon('pill')}</span><div class="grow"><h4>${state.medication?escapeHtml(state.medication.name):'Monthly preventative'}</h4><p>${name} · Vet-prescribed routine</p></div></div><div style="margin:18px 0"><span class="tag orange">NEXT DUE · OCT 15</span></div><p class="small muted" style="line-height:1.8">${state.medication?escapeHtml(state.medication.instructions):'Give the prescribed amount with food. Follow the label supplied by your vet.'}</p><div class="row" style="border-top:1px solid var(--line);padding-top:14px"><span class="tag green">Last logged Sep 15</span><span class="small muted">by Emma</span></div><div style="margin-top:17px">${action('Log administered dose','log-dose','secondary')}</div></div>${btn('Add medication','add-medication','secondary')}<p class="small muted" style="line-height:1.7;margin-top:20px">Always follow the prescription and label. Pet care does not recommend doses.</p>`);
case 'add-medication':return shell(`${back('Add medication','medications')}${form('medication',field('Medication name','name','text','','As written on the label','required')+textarea('Prescribed dose & instructions','instructions','Copy your vet’s instructions exactly','')+select('Repeat','repeat',['Once','Every day','Every week','Every month','Custom'])+field('Next dose date','date','date','2026-10-15','','required')+field('Reminder time','time','time','08:00')+field('Prescribing vet','vet','text','','Dr. Morgan'),'Save medication','medications')}`);
case 'weight':return shell(`${heading('Weight trends','Measurements, over time.','add-weight','plus')}${back('','profile')}<div class="card"><span class="small muted">LATEST WEIGHT</span><div class="price">${state.weights[0]?escapeHtml(state.weights[0].amount):pet==='milo'?'28.4':'4.8'} <small>kg</small></div><span class="tag">${state.weights[0]?'Just logged':'October 5, 2026'}</span>${weightChart()}<p class="small muted center">Weight (kg) · July–October 2026</p></div>${section('Measurements')}<div class="card list-card">${state.weights.map(w=>listRow(escapeHtml(w.amount)+' kg',escapeHtml(w.date),'weight','add-weight')).join('')}${listRow(pet==='milo'?'28.4 kg':'4.8 kg','October 5, 2026','weight','add-weight')}${listRow(pet==='milo'?'28.1 kg':'4.7 kg','September 5, 2026','weight','add-weight')}${listRow(pet==='milo'?'27.8 kg':'4.6 kg','August 5, 2026','weight','add-weight')}</div><p class="small muted">Your vet can help interpret changes.</p>`);
case 'add-weight':return shell(`${back('Log weight','weight')}${petChips()}<div class="big-icon">${icon('weight')}</div>${form('weight',`<div class="two-cols">${field('Weight','amount','number','','28.4','required min="0.1" max="1000" step="0.1"')}${select('Unit','unit',['kg','lb'])}</div>`+field('Measured on','date','date','2026-10-09','','required')+textarea('Notes (optional)','notes','e.g. Measured at the vet'),'Save weight','weight')}`);
case 'records':return shell(`${heading('Health documents','Every important little detail.','add-record','plus')}${back('','profile')}<label class="screen-search" style="margin:0 0 20px"><span>${icon('search')}</span><input data-search="records" placeholder="Search documents" aria-label="Search documents"></label><div id="record-list">${recordList('')}</div>${ad()}`);
case 'add-record':return shell(`${back('Add document','records')}<p class="form-description">Keep a copy of ${name}’s important records.</p><button class="upload-zone" data-action="upload-document">${icon('upload')}<b>${state.uploadedName?escapeHtml(state.uploadedName):'Choose a document'}</b><small>PDF, JPG, PNG · Up to 10 MB</small></button>${form('record',field('Document title','name','text',state.uploadedName||'','','required')+select('Type','type',['Vet report','Vaccination certificate','Test result','Insurance','Receipt','Other'])+field('Document date','date','date','2026-10-09')+textarea('Notes','notes','Anything you’d like to add'),'Save document','records')}<button class="text-btn small" data-go="error" style="margin-top:15px">Preview upload error state</button>`);
case 'record':return shell(`${back('Document details','records')}<div class="walk-visual">${icon('file')}<h3>${state.record?escapeHtml(state.record.name):'Annual check-up'}</h3><p class="small muted">PDF · 2 pages · 1.4 MB</p></div><div class="card"><div class="detail-grid">${info('Pet',petName())}${info('Document type',state.record?state.record.type:'Vet report')}${info('Document date',state.record?state.record.date:'24 Sep 2026')}${info('Added by','Emma Williams')}</div></div>${section('Notes')}<p class="form-description">${state.record&&state.record.notes?escapeHtml(state.record.notes):'Annual wellness visit. Keep this report for the next appointment.'}</p><div class="button-stack">${action('Preview document','preview-document','secondary')}${action('Download sample','download-record','secondary')}</div>`);
case 'visits':return shell(`${heading('Vet visits','A little planning goes a long way.','add-visit','plus')}${back('','profile')}${section('Coming up')}<div class="hero-card"><span class="tag">${state.visit?escapeHtml(state.visit.date):'THU, OCT 22'}</span><h2 style="font-size:23px">${state.visit?escapeHtml(state.visit.reason):'Annual check-up'}</h2><p>${state.visit?escapeHtml(state.visit.clinic):'Parkside Veterinary Clinic'}<br>${state.visit?escapeHtml(state.visit.time):'10:30 AM'} · ${name}</p></div><div style="margin-top:15px">${btn('Add appointment reminder','add-visit','secondary')}</div>${section('Past visits')}<div class="card list-card">${listRow('Wellness visit','Sep 24, 2026 · Dr. Morgan','calendar','record')}${listRow('Vaccination','Apr 15, 2025 · Dr. Morgan','shield','vaccines')}</div>`);
case 'add-visit':return shell(`${back('Appointment reminder','visits')}<p class="form-description">Already have an appointment? Keep the details here.</p>${form('visit',field('Reason for visit','reason','text','','e.g. Annual check-up','required')+field('Clinic','clinic','text','Parkside Veterinary Clinic','','required')+field('Date','date','date','2026-10-22','','required')+field('Time','time','time','10:30','','required')+select('Remind me','remind',['1 day before','2 hours before','1 week before'])+textarea('Questions for the vet','notes','What would you like to ask?'),'Save appointment','visits')}<p class="small muted">This creates a reminder, not a clinic booking.</p>`);
case 'vet':return shell(`${back('Vet contacts','profile')}<div class="card"><span class="tag">REGULAR VET</span><h2 style="font-size:22px">Parkside Veterinary Clinic</h2><p class="form-description">Dr. Morgan<br>24 Park Lane, London<br>Mon–Fri · 8:30 AM–6:00 PM</p>${action('Call clinic','call-clinic','secondary')}</div><div class="card"><span class="tag orange">OUT OF HOURS</span><h2 style="font-size:22px">Emergency animal hospital</h2><p class="form-description">Available 24 hours<br>Contact details saved by Emma.</p>${action('Call emergency vet','call-emergency','secondary')}</div>${btn('View emergency card','emergency')}`);
case 'emergency':return shell(`${back('Emergency card','profile')}<div class="row" style="margin-bottom:25px">${photo(pet,'large')}<div><h1 class="form-title" style="margin:0 0 6px">${name}</h1><span class="small muted">Microchip · …123 456</span></div></div><div class="card"><span class="tag red">IMPORTANT NOTES</span><p style="font-size:14px;line-height:1.7">Sensitive stomach. Contact Emma before changing food or giving any medication.</p></div><div class="button-stack">${action('Call emergency vet','call-emergency')}${action('Call Emma · Owner','call-owner','secondary')}${btn('Medication instructions','medications','secondary')}</div>${section('If you need urgent help')}<p class="form-description">Contact the nearest emergency veterinary clinic. Keep this card available to anyone looking after ${name}.</p><span class="tag">Always available · No ads</span>`);
case 'circle':return shell(`${heading('The care circle','Their people. All together.','invite','plus')}${petChips()}<div class="hero-card"><span class="tag">${name}’S PEOPLE</span><h2 style="font-size:25px">A little teamwork.<br>A lot of love.</h2><p>Everyone knows what’s done<br>and what’s still to come.</p><div class="row" style="margin-top:20px"><span class="avatar person">EW</span><span class="avatar person" style="background:#ffead8;color:#a45c24;margin-left:-19px">AC</span><span class="small">2 caregivers</span></div></div>${section('Caregivers','invite','Invite')}<div class="card list-card">${listRow('Emma Williams','Owner · Full access','users','member')}${listRow('Alex Carter','Caregiver · Meals & walks','users','member','orange')}</div>${btn('Create a sitter handoff','handoff','secondary')}${section('The latest little things','history')}<div class="card">${entry('walk','Alex logged a morning walk','9:18 AM · Milo · 32 min')}${entry('food','Emma logged breakfast','8:02 AM · Milo · 120 g')}</div>`,'circle');
case 'invite':return shell(`${back('Invite a caregiver','circle')}<div class="big-icon">${icon('users')}</div><h1 class="form-title">Make room for<br>their people.</h1><p class="form-description">Share the routine with someone you trust.</p>${form('invite',field('Email address','email','email','','alex@example.com','required')+select('Role','role',['Caregiver · Can log care','Viewer · Read only','Co-owner · Manage care'])+select('Pets to share','scope',[petName(),'All pets'])+'<div class="banner"><span class="icon-tile orange">'+icon('shield')+'</span><div><b>You stay in control.</b><p>Change or remove access anytime.</p></div></div>','Preview invitation','circle')}`);
case 'member':return shell(`${back('Caregiver details','circle')}<div class="center"><span class="avatar person large" style="margin:20px auto;font-size:25px;background:#ffead8;color:#a45c24">AC</span><h1 class="form-title">Alex Carter</h1><p class="form-description">alex@example.com</p><span class="tag orange">CAREGIVER</span></div>${form('member',select('Role','role',['Caregiver · Can log care','Viewer · Read only','Co-owner · Manage care'])+select('Access to','scope',[petName(),'All pets'])+textarea('Responsibilities','notes','','Morning and evening walks. Fresh water after each walk.'),'Save access','circle')}<button class="danger" data-action="remove-member" style="margin-top:16px">Remove caregiver</button>`);
case 'handoff':return shell(`${back('Sitter handoff','circle')}<h1 class="form-title">Away for a while?<br>Leave a little guide.</h1><p class="form-description">The important details, all in one place.</p>${form('handoff',select('Pet','pet',[petName(),'Milo & Luna'])+field('Sitter name','sitter','text','','e.g. Sam','required')+'<div class="two-cols">'+field('From','from','date','2026-10-16','','required')+field('Until','until','date','2026-10-19','','required')+'</div>'+toggle('Daily routine','Meals, walks, and care notes','routine')+toggle('Health summary','Medication and emergency details','health')+toggle('Documents','Include selected health records','documents',false)+textarea('A personal note','notes','','Milo loves his blue ball. The harness is by the front door.'),'Preview care guide','sitter')}`);
case 'sitter':return shell(`${back('Your sitter care guide','handoff')}<div class="row" style="margin:10px 0 20px">${photo(pet,'large')}<div><span class="tag orange">SITTER HANDOFF</span><h1 class="form-title" style="margin:9px 0 4px">Meet ${name}.</h1><p class="small muted">${state.handoff?'For '+escapeHtml(state.handoff.sitter):'For Sam'} · Oct 16–19</p></div></div><div class="card"><h3 style="margin-top:0">A note from Emma</h3><p class="small muted" style="line-height:1.8">${state.handoff?escapeHtml(state.handoff.notes):'Milo loves his blue ball. The harness is by the front door. He likes a little time to sniff on his walks.'}</p></div>${section('Their everyday rhythm')}<div class="card">${entry('food','8:00 AM · Breakfast','120 g of usual dry food. Fresh water.')}${entry('walk','9:00 AM · Morning walk','Park loop, around 30 minutes.')}${entry('food','6:00 PM · Dinner','120 g. Use the usual bowl.')}</div>${section('The important details')}<div class="card list-card">${listRow('Medication instructions','Follow the vet-provided label','pill','medications')}${listRow('Emergency contacts','Emma and Parkside Veterinary Clinic','phone','emergency')}</div>`,'',action('Create sharing link','create-handoff'));
case 'handoff-ready':return shell(`${back('Handoff ready','circle')}<div class="center success"><div class="big-icon">${icon('link')}</div><h1 class="form-title">Their care.<br>In good hands.</h1><p class="form-description">Your care guide is ready to share.</p></div><div class="card"><p class="small muted">SITTER</p><h3>${state.handoff?escapeHtml(state.handoff.sitter):'Sam'}</h3><p class="small muted">Expires ${state.handoff?escapeHtml(state.handoff.until):'October 19, 2026'} · Read-only guide</p><span class="tag green">${state.handoffRevoked?'Sharing stopped':'Link ready'}</span></div><div class="button-stack">${action('Copy demo sharing link','copy-handoff')}${btn('Preview guide','sitter','secondary')}${action('Stop sharing','revoke-handoff','danger')}</div><p class="small muted" style="line-height:1.7;margin-top:20px">This prototype previews sharing. It does not publish pet records or send invitations.</p>`);
case 'insights':return shell(`${heading('Little insights','See the rhythm you’re building.','history','clock')}${petChips()}<div class="segmented"><button class="active" data-action="week-insights">This week</button><button data-action="month-insights">This month</button></div><div class="card"><span class="small muted">LOGGED CARE · OCT 5–11</span><div class="price">28 <small>care moments</small></div><div class="chart">${[65,88,70,100,60,0,0].map((h,i)=>`<div class="chart-col" style="height:${h}px"><small>${['M','T','W','T','F','S','S'][i]}</small></div>`).join('')}</div><p class="small muted" style="margin-top:25px">Count of logged events. Future days are shown as zero.</p></div><div class="two-cols"><div class="card"><span class="icon-tile">${icon('walk')}</span><h2>142 min</h2><p class="small muted">Walks this week</p></div><div class="card"><span class="icon-tile orange">${icon('food')}</span><h2>10 meals</h2><p class="small muted">Meals logged</p></div></div><div class="banner"><span class="icon-tile orange">${icon('users')}</span><div><b>Care, shared equally.</b><p>Emma logged 15 moments. Alex logged 13.</p></div></div><p class="small muted">Insights reflect what you log, not a measure of your pet’s health.</p>`,'more');
case 'library':return shell(`${heading('The little care library','Good reads for their good days.','help','search')}<label class="screen-search" style="margin-top:0"><span>${icon('search')}</span><input data-search="library" placeholder="Search care topics" aria-label="Search care topics"></label><div class="pill-row">${['All','Daily care','Food','Play'].map(t=>`<button class="pill ${t==='All'?'active':''}" data-library-filter="${t}">${t}</button>`).join('')}</div><div id="article-list">${articleList()}</div>${ad()}`,'more');
case 'article':return shell(`${back('A little good read','library',`<button class="text-btn" data-action="save-article">${state.savedArticle?'Saved':'Save'}</button>`)}<article class="article"><img class="article-cover" src="assets/milo.webp" alt="Golden retriever looking curious"><span class="tag orange">DAILY CARE · 4 MIN READ</span><h1>Make a little room<br>for sniffing.</h1><p class="small muted">Pet care editorial · Sample content</p><p>A walk can be more than distance. Giving your dog time to explore familiar smells can make an everyday outing more interesting.</p><h3>Let them set the pace.</h3><p>Choose a safe route and allow a few pauses. Keep your dog on a lead where required and be mindful of other people and animals.</p><div class="banner"><div><b>A little thing to try</b><p>Take a familiar route and leave a little extra time for exploring.</p></div></div><h3>Keep their needs in mind.</h3><p>Weather, age, and comfort matter. Ask your vet about exercise needs if you’re unsure what suits your dog.</p></article>`,'',btn('Log a walk together','walk'));
case 'expenses':{let cur=state.expenseCurrency;let symbol=cur.startsWith('EUR')?'€':cur.startsWith('USD')?'$':'£';let total=(cur.startsWith('GBP')?124.50:0)+state.expenses.filter(e=>e.currency===cur).reduce((n,x)=>n+Number(x.amount),0);return shell(`${heading('Pet expenses','A little clarity on care costs.','add-expense','plus')}${back('','more')}${petChips()}<div class="hero-card"><span class="tag">OCTOBER 2026</span><h2>${symbol}${total.toFixed(2)}</h2><p>Total recorded this month · ${cur.slice(0,3)}</p></div>${cur.startsWith('GBP')?'<div class="mini-stats"><div class="stat"><b>£65</b><small>Health</small></div><div class="stat"><b>£42</b><small>Food</small></div><div class="stat"><b>£17.50</b><small>Other</small></div></div>':'<p class="small muted">Totals are grouped by currency. No exchange conversion is applied.</p>'}${section('Recent expenses')}<div class="card list-card">${state.expenses.filter(e=>e.currency===cur).map(e=>listRow(escapeHtml(e.title)+' · '+symbol+Number(e.amount).toFixed(2),escapeHtml(e.category),'wallet','add-expense')).join('')}${cur.startsWith('GBP')?listRow('Annual check-up · £65','Oct 5 · Health','heart','record','pink')+listRow('Dry food · £42','Oct 3 · Food','food','add-expense','orange')+listRow('Blue ball · £17.50','Oct 1 · Toys','pet','add-expense'):''}</div>${btn('Add expense','add-expense','secondary')}`)}
case 'add-expense':return shell(`${back('Add expense','expenses')}${petChips()}${form('expense',field('What was it for?','title','text','','e.g. Dry food','required')+'<div class="two-cols">'+field('Amount','amount','number','','0.00','required min="0.01" step="0.01"')+select('Currency','currency',['GBP (£)','EUR (€)','USD ($)'])+'</div>'+select('Category','category',['Food','Health','Grooming','Toys','Insurance','Other'])+field('Date','date','date','2026-10-09')+textarea('Notes','notes','Optional details'),'Save expense','expenses')}`);
case 'reminders':return shell(`${heading('Reminders','One less thing to remember.','add-reminder','plus')}${back('','more')}${section('Coming up')}<div class="card list-card">${state.reminders.map(r=>listRow(escapeHtml(r.title),escapeHtml(r.time)+' · '+escapeHtml(r.repeat),'bell','add-reminder')).join('')}${listRow('Evening walk','Today, 5:30 PM · Alex','walk','task')}${listRow('Monthly preventative','Oct 15, 8:00 AM · Emma','pill','medications','green')}${listRow('Annual check-up','Oct 22, 10:30 AM','calendar','visits','orange')}</div>${section('Recurring care')}<div class="card">${toggle('Morning meal','Every day · 8:00 AM','meal-reminder')}${toggle('Fresh water','Every day · 11:00 AM','water-reminder')}${toggle('Evening meal','Every day · 6:00 PM','dinner-reminder')}</div>`);
case 'add-reminder':return shell(`${back('New care reminder','reminders')}${form('reminder',field('Reminder title','title','text','','e.g. Brush Milo’s coat','required')+select('For','pet',[petName(),'All pets'])+select('Care type','type',['Meal','Walk','Medication','Grooming','Appointment','Other'])+field('Start date','date','date','2026-10-09','','required')+field('Time','time','time','17:30','','required')+select('Repeat','repeat',['Every day','Every week','Every month','Never'])+select('Assigned to','assignee',['Emma Williams','Alex Carter','Anyone in the circle'])+textarea('Care instructions','notes','Anything they should know?'),'Create reminder','reminders')}`);
case 'notifications':return shell(`${back('Your little updates','home',`<button class="text-btn small" data-action="read-all">Read all</button>`)}${section('Today')}<div class="card list-card">${listRow('Milo’s evening walk','Due at 5:30 PM · Assigned to Alex','walk','task')}${listRow('Alex logged a walk','9:18 AM · 32 minutes together','users','history','orange')}${listRow('Breakfast is logged','8:02 AM · Emma · 120 g','food','history','orange')}</div>${section('Earlier')}<div class="card list-card">${listRow('A check-up is coming up','Oct 22 · Parkside Veterinary Clinic','calendar','visits')}${listRow('Document added','Annual check-up · Emma','file','record')}</div>${btn('Notification preferences','notification-settings','secondary')}`);
case 'more':return shell(`${heading('A little more','Make Pet care feel like yours.','settings','settings')}<div class="row card"><span class="avatar person large" style="width:54px;height:54px;font-size:18px">EW</span><div class="grow"><h4>Emma Williams</h4><p>Milo & Luna’s person</p></div><button class="text-btn small" data-go="account">Edit</button></div><div class="card list-card">${listRow('Care insights','Your everyday rhythm','chart','insights')}${listRow('Pet expenses','Keep track of care costs','wallet','expenses','orange')}${listRow('Care library','A little inspiration','book','library')}${listRow('Reminders','Manage upcoming care','bell','reminders')}${listRow('Settings','Preferences and privacy','settings','settings')}${listRow('Help & support','We’re here for you','heart','help','pink')}</div><div class="hero-card" style="background:var(--ink)"><span class="tag">PET CARE PLUS</span><h2 style="font-size:24px">More quiet.<br>Same big love.</h2><p>An ad-free home for your pet’s care.</p><button class="secondary" style="margin-top:17px;min-height:43px" data-go="premium">Explore Plus</button></div>${ad()}`,'more');
case 'settings':return shell(`${back('Settings','more')}<div class="card list-card">${listRow('Your account','Emma Williams','users','account')}${listRow('Notifications','Care reminders and updates','bell','notification-settings')}${listRow('Privacy & ads','Your data and preferences','shield','privacy')}${listRow('Pet care Plus','Manage your plan','heart','premium','orange')}</div>${section('Preferences')}<div class="card">${select('Weight unit','weightUnit',['Kilograms (kg)','Pounds (lb)'])}${select('Currency','currency',['GBP (£)','EUR (€)','USD ($)'])}${select('Time format','timeFormat',['12-hour','24-hour'])}${select('Language','language',['English','Deutsch','Français','Español'])}</div><p class="small muted">Localization preview · English content</p><div class="card list-card">${listRow('Export my data','Download a copy of your care log','download','passport')}${listRow('Help & support','Questions and feedback','book','help')}</div>${action('Sign out','signout','secondary')}<p class="center small muted" style="margin-top:25px">Pet care 1.0 · Made for the little things.</p>`);
case 'account':return shell(`${back('Your account','settings')}<div class="center"><span class="avatar person large" style="margin:20px auto;font-size:24px">EW</span></div>${form('account',field('Name','name','text','Emma Williams','','required')+field('Email','email','email','emma@example.com','','required')+select('Country / region','region',['United Kingdom','United States','Germany','France','Other']),'Save account','settings')}<div style="margin-top:22px">${btn('Reset password','forgot','secondary')}</div><button class="text-btn" style="color:var(--red);width:100%;margin-top:25px" data-go="delete">Delete account</button>`);
case 'notification-settings':return shell(`${back('Notifications','settings')}<div class="banner"><span class="icon-tile">${icon('bell')}</span><div><b>Gentle, useful reminders.</b><p>Choose what belongs in your day.</p></div></div><div class="card">${toggle('Care reminders','Meals, walks, and your routines','care')}${toggle('Medication reminders','Your prescribed-care schedule','medication')}${toggle('Vet appointments','Upcoming visits and follow-ups','appointments')}${toggle('Care circle updates','When someone logs care','circle')}${toggle('Tips & product updates','Optional Pet care news','marketing',false)}</div>${section('Quiet hours')}<div class="card">${toggle('Quiet hours','Pause optional updates overnight','quiet')}${field('From','quietFrom','time','22:00')}${field('Until','quietUntil','time','07:00')}</div><p class="small muted">Time-critical care reminders use your selected schedule.</p>`,'',action('Save preferences','save-preferences'));
case 'privacy':return shell(`${back('Privacy & ads',current==='privacy'?'settings':'consent')}<h1 class="form-title">Your care.<br>Your choices.</h1><p class="form-description">Change your preferences whenever you like.</p><div class="card">${toggle('Essential storage','Required for sign-in and your care settings.','essential',true)}${toggle('Personalized ads','Allow ad-related data to tailor ads.','personalized',state.consent)}${toggle('Optional analytics','Help improve the experience.','analytics',false)}</div><p class="small muted" style="line-height:1.7">Health records and care notes are shared only with the people you give access to. Ad partners do not receive these records.</p><div class="card list-card">${listRow('Manage shared access','Review your care circle','users','circle')}${listRow('Export your data','Preview your pet-care summary','download','passport')}${listRow('Delete your account','Account and care data controls','shield','delete')}</div><div class="two-cols">${action('Privacy policy','privacy-policy','secondary')}${action('Terms','terms','secondary')}</div>`,'',action('Save my choices','save-consent'));
case 'premium':return shell(`${back('Pet care Plus','more')}<img class="center-art" style="width:150px;height:150px;margin-top:0" src="assets/cozy-friends.webp" alt="Dog and cat"><div class="center"><span class="tag orange">A LITTLE EXTRA</span><h1 class="form-title" style="margin-top:17px">More quiet.<br>Same big love.</h1><p class="form-description">Your pet’s everyday care, without ads.</p></div><div class="card"><span class="tag">MONTHLY PLAN · CONCEPT PRICE</span><div class="price">$2.99 <small>/ month</small></div>${['No sponsored placements','Custom care-report themes','All essential care stays free'].map(x=>`<div class="feature-row">${icon('check')}${x}</div>`).join('')}<p class="small muted">Cancel through your app-store account. Regional pricing may vary.</p></div><p class="small muted center">Purchases are simulated in this prototype.</p>`,'',`<div class="button-stack">${action('Preview Plus upgrade','upgrade')}${action('Restore purchases','restore','secondary')}</div>`);
case 'help':return shell(`${back('A little help','more')}<h1 class="form-title">We’re here<br>for you.</h1><label class="screen-search"><span>${icon('search')}</span><input data-search="help" placeholder="Search help" aria-label="Search help"></label><div id="help-list">${helpList()}</div>${section('Still need a hand?')}${action('Contact support','support','secondary')}<p class="small muted" style="line-height:1.8">For pet-health concerns, contact your vet. This support channel is for using Pet care.</p>`);
case 'empty':return shell(`<div class="center"><img class="center-art" style="width:265px;height:265px;margin-top:75px" src="assets/cozy-friends.webp" alt="Dog and cat"><h1 class="form-title">A little home<br>waiting for them.</h1><p class="form-description">Add your first pet to start their story.</p></div>`,'',btn('Add my first pet','add-pet'));
case 'offline':return shell(`${back('Connection status','home')}<div class="center"><div class="big-icon" style="margin-top:80px">${icon('shield')}</div><h1 class="form-title">A little pause<br>in connection.</h1><p class="form-description">You can view saved care information.<br>New entries will sync when you’re back.</p></div><div class="card row"><span class="icon-tile orange">${icon('clock')}</span><div><h4>2 care entries waiting to sync</h4><p>Last synced today at 9:18 AM</p></div></div><p class="small muted center">State preview · offline storage is simulated.</p>`,'',`<div class="button-stack">${action('Try reconnecting','reconnect')}${btn('View emergency card','emergency','secondary')}</div>`);
case 'error':return shell(`${back('Add document','add-record')}<div class="big-icon" style="color:var(--red);background:#fbedee;margin-top:70px">${icon('alert')}</div><h1 class="form-title center">That didn’t<br>quite go through.</h1><p class="form-description center">Your document hasn’t uploaded.<br>Your details are still here.</p><div class="card row"><span class="icon-tile">${icon('file')}</span><div><h4>${state.uploadedName?escapeHtml(state.uploadedName):'Annual-check-up.pdf'}</h4><p>Connection interrupted</p></div></div><div class="error-box">Check your connection, then try again. You can also return and choose a different file.</div>`,'',`<div class="button-stack">${action('Try upload again','retry-upload')}${btn('Back to document','add-record','secondary')}</div>`);
case 'delete':return shell(`${back('Delete account','account')}<div class="big-icon" style="color:var(--red);background:#fbedee">${icon('alert')}</div><h1 class="form-title">Before you go.</h1><p class="form-description">Deleting your account removes your profiles, care history, and saved documents. Export anything you want to keep first.</p><div class="card"><h4 style="margin-top:0">Your care circle</h4><p class="small muted" style="line-height:1.8">Transfer pet ownership before deletion if another caregiver will keep using the shared profile.</p></div>${form('delete',field('Type DELETE to confirm','confirm','text','','DELETE','required pattern="DELETE"')+'<label class="check-field"><input type="checkbox" required><span>I understand that deletion cannot be undone.</span></label>','Delete account','welcome')}<p class="small muted center">Demo confirmation only. No real account is deleted.</p>`);
default:return shell('<h1>Screen not found</h1>');}}
function entry(i,title,sub){return `<div class="timeline-entry"><span class="timeline-mark">${icon(i)}</span><div><b>${title}</b><p>${sub}</p></div></div>`}
function timeline(full=false){return `<div class="card">${state.history.slice(0,full?20:2).map(x=>entry(x.type,escapeHtml(x.title),escapeHtml(x.sub))).join('')}${entry('walk','Morning walk','9:18 AM · Alex · '+petName()+' · 32 min')}${entry('food','Breakfast','8:02 AM · Emma · '+petName()+' · 120 g')}${full?entry('heart','Fresh water','11:00 AM · Emma · '+petName()):''}</div>`}
function timeString(n){return [Math.floor(n/3600),Math.floor(n%3600/60),n%60].map(v=>String(v).padStart(2,'0')).join(':')}
function weightChart(){let vals=pet==='milo'?[27.5,27.8,28.1,28.4]:[4.5,4.6,4.7,4.8];let top=pet==='milo'?29:5.1,step=pet==='milo'?1:.3;let xs=[35,115,195,280],ys=vals.map(v=>20+(top-v)/step*32);let path=xs.map((x,i)=>(i?'L':'M')+x+' '+ys[i]).join(' ');return `<svg class="line-chart" role="img" aria-label="Weight in kilograms, July to October: ${vals.join(', ')}" viewBox="0 0 300 145"><path d="M30 20H290 M30 52H290 M30 84H290 M30 116H290" stroke="#e9ecf4" fill="none"/>${[0,1,2].map(i=>`<text x="0" y="${25+i*32}">${(top-i*step).toFixed(1)}</text>`).join('')}<path d="${path} L280 116 L35 116Z" fill="#eee7ff"/><path d="${path}" fill="none" stroke="#7549ef" stroke-width="3" stroke-linecap="round"/>${xs.map((x,i)=>`<circle cx="${x}" cy="${ys[i]}" r="5" fill="#7549ef" stroke="white" stroke-width="2"/>`).join('')}<text x="30" y="140">Jul</text><text x="105" y="140">Aug</text><text x="187" y="140">Sep</text><text x="265" y="140">Oct</text></svg>`}
function recordList(q){const docs=[...(state.record?[state.record.name]:[]),'Annual check-up','Vaccination certificate','Blood test results'];return docs.filter(t=>t.toLowerCase().includes(q.toLowerCase())).map((t,i)=>`<div class="card list-card">${listRow(escapeHtml(t),['Sep 24, 2026 · PDF · 1.4 MB','Apr 15, 2025 · PDF · 640 KB','Sep 24, 2026 · PDF · 920 KB'][i%3],'file','record')}</div>`).join('')||'<div class="card center"><h3>No matching documents</h3><p class="small muted">Try a different title.</p></div>'}
function articleList(q='',filter='All'){const data=[['Make a little room for sniffing.','Daily care','assets/milo.webp'],['Play, their way.','Play','assets/luna.webp'],['A calmer mealtime routine.','Food','assets/cozy-friends.webp']];return data.filter(([t,c])=>t.toLowerCase().includes(q.toLowerCase())&&(filter==='All'||filter===c)).map(([t,c,img],i)=>`<button class="card" data-go="article" style="width:100%;text-align:left;color:var(--ink);padding:12px"><img class="article-cover" style="height:${i?'120':'190'}px;margin-bottom:13px" src="${img}" alt="Pet care inspiration"><span class="tag ${i?'':'orange'}">${c.toUpperCase()} · 4 MIN READ</span><h3 style="margin:12px 4px;font-size:19px;letter-spacing:-.5px">${t}</h3></button>`).join('')||'<div class="card center"><p>No matching topics. Try another search.</p></div>'}
function helpList(q=''){return ['How do I invite a caregiver?','Can I change reminder times?','How do I export a pet’s records?','How do I manage ad preferences?'].filter(x=>x.toLowerCase().includes(q.toLowerCase())).map((x,i)=>`<div class="card"><details><summary style="cursor:pointer;font-size:14px;font-weight:650;line-height:1.5">${x}</summary><p class="small muted" style="line-height:1.8">${['Open Care circle, choose Invite, then select the role and pets to share. You can change access later.','Open Reminders, select the care reminder, and adjust the time and repeat pattern.','Open your pet’s Health passport and choose export. Review the summary before sharing it.','Open Settings, then Privacy & ads. You can change optional preferences at any time.'][i]}</p></details></div>`).join('')||'<div class="card"><p class="small muted">No matching help topics. Try another search.</p></div>'}
const flows={
'Getting started':[['Welcome','welcome'],['Create an account','signup'],['Set ad preferences','consent'],['Add your pet','add-pet']],
'Pet setup':[['Add a pet','add-pet'],['Pet details','pet-details'],['Build a routine','routine-setup'],['Finish setup','ready']],
'Daily care':[['Check today','home'],['Log a meal','feeding'],['See care history','history'],['Create a reminder','add-reminder']],
'Pets & health':[['Pet profile','profile'],['Add a health record','add-record'],['Health passport','passport'],['Emergency contacts','emergency']],
'Shared care':[['Invite a caregiver','invite'],['Prepare a handoff','handoff'],['Review the guide','sitter'],['Sharing controls','handoff-ready']],
'Explore & more':[['Care insights','insights'],['Browse care ideas','library'],['Track expenses','expenses'],['Manage reminders','reminders']],
'Account & states':[['Settings','settings'],['Ad preferences','privacy'],['Preview an empty state','empty'],['Preview an upload error','error']]
};
function renderNav(){const q=document.getElementById('screen-search').value.toLowerCase();document.getElementById('screen-nav').innerHTML=groups.map(g=>{const a=screens.filter(s=>s.group===g&&s.title.toLowerCase().includes(q));return a.length?`<div class="nav-group"><div class="nav-group-heading"><span>${g}</span><span>${a.length}</span></div>${a.map(s=>`<button class="nav-item ${s.id===current?'active':''}" data-go="${s.id}" ${s.id===current?'aria-current="page"':''}>${s.title}</button>`).join('')}</div>`:''}).join('')||'<p class="small muted">No matching screens.</p>'}
function render(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('prototype-view').hidden=view!=='prototype';document.getElementById('gallery-view').hidden=view!=='gallery';document.getElementById('system-view').hidden=view!=='system';renderNav();document.getElementById('screen-count').textContent=screens.length;const s=screens.find(s=>s.id===current);document.getElementById('stage-group').textContent=s.group.toUpperCase();document.getElementById('stage-title').textContent=s.title;document.getElementById('screen-position').textContent=`${String(screens.indexOf(s)+1).padStart(2,'0')} / ${screens.length}`;document.getElementById('note-title').textContent=s.title;document.getElementById('note-text').textContent=s.note;document.getElementById('flow-links').innerHTML=flows[s.group].map(([t,id],i)=>`<button class="flow-link" data-go="${id}"><span>${i+1}</span>${t}</button>`).join('');if(view==='prototype'){document.getElementById('phone-content').innerHTML=screen(current);if(current==='privacy')document.querySelector('input[name=essential]').disabled=true}if(view==='gallery')renderGallery();if(view==='system')renderSystem();document.title='Pet care — '+(view==='prototype'?s.title:view==='gallery'?'All screens':'Brand & UX')}
function renderGallery(){document.getElementById('gallery-filters').innerHTML=['All',...groups].map(g=>`<button data-gallery-group="${g}" class="${g===galleryGroup?'active':''}">${g}</button>`).join('');document.getElementById('gallery-grid').innerHTML=screens.filter(s=>galleryGroup==='All'||s.group===galleryGroup).map(s=>`<div class="gallery-card" role="button" tabindex="0" data-go="${s.id}" aria-label="Explore ${s.title}"><div class="gallery-card-head"><span>${String(screens.indexOf(s)+1).padStart(2,'0')}</span>${s.title}</div><div class="gallery-phone-wrap"><div class="phone gallery-phone"><div class="statusbar"><b>9:41</b><span class="island"></span><span>▮▮▮ Wi-Fi ▰</span></div><div style="height:794px">${screen(s.id)}</div><div class="home-indicator"></div></div></div></div>`).join('')}
function renderSystem(){document.getElementById('system-view').innerHTML=`<div class="system"><div class="system-hero"><div><span class="eyebrow" style="color:#d4ddff">THE BRAND / PET CARE</span><h1>Pet care</h1><h2>A little care.<br>A lot of love.</h2><p>A cheerful, practical companion for people who share life with pets. Care feels simple, human, and connected.</p><span class="tag" style="color:white;background:#ffffff20">WORKING BRAND · V1.0</span></div><img src="assets/cozy-friends.webp" alt="Pet care’s dog and cat illustration"></div><h2 class="system-title">Color, with a little character.</h2><div class="swatches">${[['Pet care blue','#2854F4','Primary actions'],['Apricot','#FF9F4B','Warm accents'],['Midnight','#17203B','Text & contrast'],['Cloud','#F4F6FB','Backgrounds'],['Care green','#16774F','Confirmed states']].map(([n,c,use])=>`<div class="swatch"><div style="background:${c}"></div><p>${n}<small>${c} · ${use}</small></p></div>`).join('')}</div><h2 class="system-title">The foundations.</h2><div class="system-grid"><div class="system-card"><span class="eyebrow">TYPOGRAPHY</span><h2 style="font-size:36px;line-height:1.1;letter-spacing:-1.4px;margin:20px 0">Good days start<br>with little things.</h2><p>Native system typography: SF Pro on iOS, platform sans-serif on Android. Familiar, fast, and naturally accessible.</p><table class="system-table"><tr><th>Role</th><th>Size / weight</th></tr><tr><td>Onboarding heading</td><td>38 / 750</td></tr><tr><td>Page heading</td><td>24–30 / 700</td></tr><tr><td>Body & controls</td><td>14–16 / 400–650</td></tr><tr><td>Supporting metadata</td><td>12 / 400</td></tr></table></div><div class="system-card"><span class="eyebrow">VOICE & PERSONALITY</span><h3 style="margin-top:20px">Warm. Clear. Never judgmental.</h3><p>Celebrate small care moments. Use names and plain words. Keep essential instructions practical.</p><table class="system-table"><tr><th>Moment</th><th>Copy</th></tr><tr><td>Completion</td><td>A little care. All logged.</td></tr><tr><td>Empty state</td><td>A little home waiting for them.</td></tr><tr><td>Error</td><td>That didn’t quite go through.</td></tr><tr><td>Sharing</td><td>Their people. One care circle.</td></tr></table><p>Medical details use neutral labels and vet-provided instructions. Avoid guilt, health scores, and diagnostic claims.</p></div></div><h2 class="system-title">A consistent little toolkit.</h2><div class="component-grid"><div class="system-card"><h3>Actions</h3><div class="button-stack">${btn('Primary action','home')}${btn('Secondary action','gallery','secondary')}${action('Destructive action','component-danger','danger')}</div><p>50 px minimum button height. Clear labels. Full-width primary action in focused forms.</p></div><div class="system-card"><h3>Care statuses</h3><div class="pill-row"><span class="tag green">${icon('check')} Logged</span><span class="tag orange">Coming up</span><span class="tag red">Action needed</span><span class="tag">Shared care</span></div><div class="task-row"><span class="icon-tile orange">${icon('food')}</span><div class="grow"><b style="font-size:14px">Morning meal</b><p class="small muted">8:00 AM · Emma</p></div><span class="check-btn done">${icon('check')}</span></div><p>Text accompanies every status. Color adds meaning without being the only signal.</p></div><div class="system-card"><h3>Form patterns</h3>${field('Pet’s name','componentName','text','Milo')}<label class="field error"><span>Email address</span><input value="emma@" aria-invalid="true"><small>Enter a complete email address.</small></label><p>Persistent labels, suitable input keyboards, inline validation, and explicit save feedback.</p></div></div><h2 class="system-title">Original assets.</h2><div class="asset-grid">${[['milo','Golden retriever · Apricot'],['luna','British shorthair · Periwinkle'],['friends','Onboarding · Tactile 3D']].map(([f,t])=>`<div><img src="assets/${f}.webp" alt="${t}"><p>${t} · AI-generated asset</p><a class="text-btn small" href="assets/${f}.webp" download="pet-care-${f}.webp">Download asset</a></div>`).join('')}</div><h2 class="system-title">The UX blueprint.</h2><div class="system-grid"><div class="system-card"><h3>Navigation & key journeys</h3><p>Five stable destinations: Today, Pets, Log, Circle, and More. Focused forms use a clear back action and one save button.</p><table class="system-table"><tr><th>Journey</th><th>Sequence</th></tr><tr><td>First visit</td><td>Welcome → Account → Consent → Pet → Routine</td></tr><tr><td>Daily care</td><td>Today → Log care → Confirmation → Timeline</td></tr><tr><td>Health</td><td>Pet → Records → Passport → Export</td></tr><tr><td>Sitter</td><td>Circle → Handoff → Review → Share</td></tr></table></div><div class="system-card"><h3>The distinguishing experience</h3><p>A single shared care timeline answers who did what. Time-bound sitter handoffs turn that same routine into a practical guide.</p><ul><li>Ownership, caregiver, and viewer roles.</li><li>Pet-specific shared access.</li><li>Explicit handoff expiry and revocation.</li><li>Portable health and emergency summary.</li></ul><p>App-store differentiation still depends on the shipped implementation and review; this is a design direction.</p></div><div class="system-card"><h3>AdMob placement principles</h3><ul><li>Native-style ad slots only in browse views.</li><li>No ads in emergency, medication, consent, or logging flows.</li><li>Sponsored content visibly labelled and separated.</li><li>Equal-choice consent controls and later opt-out.</li><li>Optional Plus plan; essential care remains free.</li></ul><p>Shown placements and pricing are concepts. Consent, AdMob, ATT where applicable, and store purchases require native implementation.</p></div><div class="system-card"><h3>Accessibility & native handoff</h3><ul><li>Safe areas and keyboard-aware forms.</li><li>44 pt iOS / 48 dp Android minimum touch targets.</li><li>Screen-reader labels and visible focus states.</li><li>Dynamic type and reduced-motion support.</li><li>Localized dates, units, currency, and time zones.</li><li>Explicit empty, offline, upload-error, and success states.</li></ul><p>This web prototype demonstrates layout and flows. Native accessibility and service behavior need implementation testing.</p></div></div><h2 class="system-title">Complete screen inventory · ${screens.length} screens.</h2><div class="system-card"><table class="system-table"><tr><th>Area</th><th>Screens</th><th>Coverage</th></tr>${groups.map(g=>`<tr><td>${g}</td><td>${screens.filter(s=>s.group===g).length}</td><td>${screens.filter(s=>s.group===g).map(s=>s.title).join(' · ')}</td></tr>`).join('')}</table></div><h2 class="system-title">Build-ready conventions.</h2><div class="system-card"><table class="system-table"><tr><th>Token / pattern</th><th>Specification</th></tr><tr><td>Spacing</td><td>4, 8, 12, 16, 20, 24, 32 px; 22 px mobile content margin.</td></tr><tr><td>Corners</td><td>12–16 px controls; 18–24 px cards; 26–32 px hero imagery.</td></tr><tr><td>Data ownership</td><td>Pet → Care events, routines, records, measurements, and access grants.</td></tr><tr><td>Shared completion</td><td>Each event has actor, pet, event time, and sync state; prevent duplicate completion on the backend.</td></tr><tr><td>Files & exports</td><td>Authenticated storage, upload progress, readable errors, scoped sharing, and revocation.</td></tr><tr><td>Notifications</td><td>Time-zone aware schedules; caregiver attribution; no duplicate reminders after sync.</td></tr><tr><td>Prototype boundary</td><td>In-memory demo state. Authentication, uploads, invitations, sync, payments, and push delivery are simulated.</td></tr></table><div class="pill-row">${btn('Explore every screen','home','secondary')}<button class="primary" data-view="gallery">Open screen gallery</button></div></div></div>`}
let toastTimer;function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3300)}
function modal(title,body,actions=''){document.getElementById('demo-dialog')?.remove();let d=document.createElement('dialog');d.id='demo-dialog';d.className='demo-dialog';d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close-dialog" class="icon-btn" aria-label="Close">${icon('close')}</button></div>${body}<div class="button-stack">${actions||'<button class="primary" data-action="close-dialog">Got it</button>'}</div>`;document.body.append(d);d.showModal();d.addEventListener('click',e=>{if(e.target===d)d.close()})}
function nativeDemo(title,body){modal(title,`<p>${body}</p><div class="banner"><div><b>Design prototype</b><p>This previews a native app service. No external action is performed.</p></div></div>`)}
function downloadText(filename,text,mime='text/plain'){const url=URL.createObjectURL(new Blob([text],{type:mime}));let a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function handleAction(a){switch(a){
case 'close-dialog':document.getElementById('demo-dialog')?.close();break;
case 'allow-ads':state.consent=true;go('permissions');break;
case 'decline-ads':state.consent=false;go('permissions');break;
case 'enable-reminders':modal('Enable care reminders',`<p>In the native app, the operating system will ask permission to send reminders.</p><p class="small muted">No permission is requested by this design prototype.</p>`,action('Continue to pet setup','continue-permissions'));break;
case 'continue-permissions':go('add-pet');break;
case 'task-done':{let t=state.tasks.find(t=>t.id===state.taskOpen);if(!t){toast('Create a care reminder first.');go('add-reminder');break}t.done=!t.done;toast(t.done?'Care marked as done.':'Completion undone.');render();break}
case 'timer-toggle':walkRunning=!walkRunning;if(walkRunning){walkInterval=setInterval(()=>{walkSeconds++;const el=document.getElementById('walk-timer');if(el)el.textContent=timeString(walkSeconds)},1000)}else{clearInterval(walkInterval)}render();break;
case 'log-dose':modal('Confirm administered dose',`<p>Confirm you have already given ${escapeHtml(petName())} the dose prescribed by your vet.</p><p class="small muted">This records administration. It does not recommend a dose.</p>`,`${action('Confirm dose given','confirm-dose')}${action('Cancel','close-dialog','secondary')}`);break;
case 'confirm-dose':document.getElementById('demo-dialog').close();state.history.unshift({type:'pill',title:'Medication administered',sub:'Just now · Emma · '+petName()});go('care-saved');break;
case 'save-preferences':toast('Notification preferences saved in this demo.');go('settings');break;
case 'save-consent':state.consent=document.querySelector('#phone-content input[name=personalized]')?.checked||false;toast('Ad preferences saved.');go('settings');break;
case 'upload-photo':{let inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.onchange=()=>{const f=inp.files[0];if(!f)return;if(f.size>10*1024*1024){toast('Choose a photo smaller than 10 MB.');return}if(state.petPhoto)URL.revokeObjectURL(state.petPhoto);state.petPhoto=URL.createObjectURL(f);toast('Photo selected for this demo.');render()};inp.click();break}
case 'upload-document':{let inp=document.createElement('input');inp.type='file';inp.accept='.pdf,.jpg,.jpeg,.png';inp.onchange=()=>{const f=inp.files[0];if(!f)return;if(f.size>10*1024*1024){toast('Choose a document smaller than 10 MB.');return}state.uploadedName=f.name;toast('File selected locally. No upload occurs in this prototype.');render()};inp.click();break}
case 'preview-document':nativeDemo('Document preview','A native document viewer will display your PDF or image here.');break;
case 'download-record':downloadText('Pet care-Sample-Record.txt','PET CARE SAMPLE DOCUMENT\nThis is a UI prototype export, not a real veterinary record.\nPet: '+petName()+'\nDocument: '+(state.record?.name||'Annual check-up'));toast('Sample record downloaded.');break;
case 'export-passport':downloadText('Pet care-'+petName()+'-Passport.txt','PET CARE SAMPLE HEALTH PASSPORT\nDesign prototype data only. Not an official travel document.\n\nPet: '+petName()+'\nMicrochip: 985 141 004 123 456\nCare contact: Emma Williams\nClinic: Parkside Veterinary Clinic\n\nCARE EVENTS\n'+state.history.map(x=>x.title+' — '+x.sub).join('\n'));toast('Sample passport exported.');break;
case 'create-handoff':go('handoff-ready');break;
case 'copy-handoff':{const link='https://example.com/pet-care/demo-care-guide';if(state.handoffRevoked){toast('Sharing has been stopped. Create a new handoff.');break}if(navigator.clipboard){navigator.clipboard.writeText(link).then(()=>toast('Demo link copied. This is not a live care guide.')).catch(()=>modal('Demo sharing link',`<p class="small" style="word-break:break-all">${link}</p>`))}else modal('Demo sharing link',`<p class="small">${link}</p>`);break}
case 'revoke-handoff':state.handoffRevoked=true;render();toast('Sharing stopped in this demo.');break;
case 'remove-member':modal('Remove Alex’s access?',`<p>Alex will no longer be able to view or log care for ${escapeHtml(petName())}.</p>`,`${action('Remove access','confirm-remove','danger')}${action('Keep caregiver','close-dialog','secondary')}`);break;
case 'confirm-remove':document.getElementById('demo-dialog').close();toast('Caregiver removal previewed. Demo members are retained.');go('circle');break;
case 'save-article':state.savedArticle=!state.savedArticle;render();toast(state.savedArticle?'Article saved.':'Article removed from saved items.');break;
case 'signout':go('welcome');toast('Signed out of the demo.');break;
case 'read-all':toast('All updates marked as read in this demo.');break;
case 'reconnect':toast('Demo connection restored. Care entries synced.');go('home');break;
case 'retry-upload':go('add-record');toast('Retry ready. Choose a file and save its details.');break;
case 'upgrade':nativeDemo('Pet care Plus','The native app will open the App Store or Google Play purchase confirmation. This demo does not charge you.');break;
case 'restore':nativeDemo('Restore purchases','The native app will check for an existing subscription on your store account.');break;
case 'social-apple':case 'social-google':nativeDemo(a==='social-apple'?'Continue with Apple':'Continue with Google','An account-provider sign-in screen will open in the native app.');break;
case 'call-clinic':case 'call-emergency':case 'call-owner':nativeDemo('Call contact','The native app will open the phone dialer with your saved contact number. Sample contacts in this prototype are not dialed.');break;
case 'ad-demo':nativeDemo('Sponsored content','This is a sample ad slot showing placement and visual separation. No live AdMob ad is loaded.');break;
case 'support':modal('Contact Pet care support',`<p>Tell us what you were trying to do.</p><form data-form="support" data-next="help">${field('Email','email','email','','emma@example.com','required')}${textarea('Your message','message','How can we help?')}<button class="primary" type="submit">Preview support request</button></form>`);break;
case 'privacy-policy':modal('Privacy policy · draft outline','<p>Production policy should identify the data controller, service providers, processing purposes, retention, rights, contact details, and regional consent handling.</p><p>This design uses sample data and in-memory state. Selected files remain local and are not uploaded. No live advertising or analytics SDK is included.</p>');break;
case 'terms':modal('Terms · draft outline','<p>The production terms should cover accounts, shared-access responsibilities, subscription conditions, content, acceptable use, and service limitations.</p><p>Pet care organizes owner-entered care information. It does not replace veterinary advice or issue official travel documents. This is a design prototype.</p>');break;
case 'month-insights':toast('Monthly range is a layout preview. This screen shows sample weekly data.');break;
case 'week-insights':toast('Showing sample care logs for October 5–11.');break;
case 'calendar-demo':toast('This prototype shows a sample weekly routine.');break;
case 'component-danger':toast('Destructive button style preview.');break;
}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-go],[data-view],[data-action],[data-pet],[data-task],[data-complete],[data-filter],[data-date],[data-mood],[data-open-pet],[data-gallery-group],[data-library-filter]');if(!b)return;
if(b.dataset.go){if(b.dataset.go==='gallery'){view='gallery';render()}else{if(b.dataset.go==='walk-summary'){walkRunning=false;clearInterval(walkInterval)}go(b.dataset.go)}}
else if(b.dataset.view){view=b.dataset.view;render()}
else if(b.dataset.action)handleAction(b.dataset.action);
else if(b.dataset.pet){pet=b.dataset.pet;render()}
else if(b.dataset.openPet){pet=b.dataset.openPet;go('profile')}
else if(b.dataset.task){state.taskOpen=Number(b.dataset.task);go('task')}
else if(b.dataset.complete){let t=state.tasks.find(t=>t.id===Number(b.dataset.complete));t.done=!t.done;render();toast(t.done?'Care logged. Your circle is up to date.':'Completion undone.')}
else if(b.dataset.filter){taskFilter=b.dataset.filter;render()}
else if(b.dataset.date){dateSelected=Number(b.dataset.date);render()}
else if(b.dataset.mood){mood=b.dataset.mood;render()}
else if(b.dataset.galleryGroup){galleryGroup=b.dataset.galleryGroup;renderGallery()}
else if(b.dataset.libraryFilter){document.querySelectorAll('[data-library-filter]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('article-list').innerHTML=articleList('',b.dataset.libraryFilter)}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.gallery-card')){e.preventDefault();go(e.target.dataset.go)}});
document.addEventListener('input',e=>{if(e.target.dataset.search==='records')document.getElementById('record-list').innerHTML=recordList(e.target.value);if(e.target.dataset.search==='library')document.getElementById('article-list').innerHTML=articleList(e.target.value);if(e.target.dataset.search==='help')document.getElementById('help-list').innerHTML=helpList(e.target.value)});
document.addEventListener('change',e=>{if(e.target.name==='essential'){e.target.checked=true;toast('Essential storage is required for the service.')}});
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));let next=f.dataset.next;switch(f.dataset.form){
case 'signup':case 'signin':toast('Account flow previewed. No real account was created.');break;
case 'forgot':toast('Recovery screen previewed. No email was sent.');break;
case 'add-pet':state.petName=d.petName;state.newPet=true;pet='milo';break;
case 'pet-details':break;
case 'routine':{const meals=f.querySelector('[name=meals]').checked,walks=f.querySelector('[name=walks]').checked,water=f.querySelector('[name=water]').checked;state.tasks=[];if(meals)state.tasks.push({id:1,title:'Morning meal',sub:displayTime(d.morning)+' · Emma',type:'food',done:false},{id:5,title:'Evening meal',sub:displayTime(d.evening)+' · Emma',type:'food',done:false});if(walks)state.tasks.push({id:2,title:'Morning walk',sub:'9:00 AM · Alex',type:'walk',done:false},{id:4,title:'Evening walk',sub:'5:30 PM · Alex',type:'walk',done:false});if(water)state.tasks.push({id:3,title:'Fresh water',sub:'11:00 AM · Emma',type:'heart',done:false});if(!state.tasks.length){toast('Routine saved. Add a reminder whenever you’re ready.')}break}
case 'edit-pet':if(pet==='milo')state.petName=d.petName;else state.catName=d.petName;toast('Pet details saved.');break;
case 'feeding':state.history.unshift({type:'food',title:d.meal+' · '+d.amount+' '+d.unit,sub:displayTime(d.time)+' · Emma · '+petName()});break;
case 'walk-summary':state.history.unshift({type:'walk',title:'Walk · '+d.duration+' min',sub:displayTime(d.time)+' · Emma · '+petName()});walkSeconds=0;break;
case 'wellbeing':state.history.unshift({type:'heart',title:'Feeling '+mood.toLowerCase(),sub:'Just now · Emma · '+petName()});break;
case 'vaccine':state.vaccine=d;toast('Vaccination recorded.');break;
case 'medication':if(!d.instructions.trim()){toast('Add the instructions from your vet before saving.');return}state.medication=d;toast('Medication saved.');break;
case 'weight':if(d.unit==='lb')d.amount=(Number(d.amount)/2.20462).toFixed(1);state.weights.unshift(d);toast('Weight measurement saved.');break;
case 'record':if(!state.uploadedName){toast('Choose a document before saving.');return}state.record=d;toast('Document details saved locally. File upload is simulated.');break;
case 'visit':state.visit=d;toast('Appointment reminder saved.');break;
case 'invite':state.invite=d;modal('Invitation preview',`<p><b>${escapeHtml(d.email)}</b> will be invited as <b>${escapeHtml(d.role)}</b> for <b>${escapeHtml(d.scope)}</b>.</p><p class="small muted">No invitation is sent in this prototype.</p>`,`${btn('Back to care circle','circle')}`);return;
case 'member':toast('Access settings previewed.');break;
case 'handoff':if(d.until<d.from){toast('Choose an end date after the start date.');return}state.handoff=d;state.handoffRevoked=false;break;
case 'expense':state.expenses.unshift(d);state.expenseCurrency=d.currency;toast('Expense saved.');break;
case 'reminder':state.reminders.unshift(d);state.tasks.push({id:Date.now(),title:d.title,sub:displayTime(d.time)+' · '+d.assignee.split(' ')[0],type:d.type==='Meal'?'food':d.type==='Walk'?'walk':'bell',done:false});toast('Reminder added.');break;
case 'account':toast('Account changes previewed.');break;
case 'delete':resetState();toast('Account deletion previewed. No real data was deleted.');break;
case 'support':document.getElementById('demo-dialog')?.close();toast('Support request previewed. No message was sent.');break;
}go(next)});
function displayTime(v){if(!v)return '';let [h,m]=v.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
document.getElementById('screen-search').addEventListener('input',renderNav);document.getElementById('prev-screen').onclick=()=>go(screens[(screens.findIndex(s=>s.id===current)+screens.length-1)%screens.length].id);document.getElementById('next-screen').onclick=()=>go(screens[(screens.findIndex(s=>s.id===current)+1)%screens.length].id);document.getElementById('reset').onclick=()=>{resetState();pet='milo';taskFilter='All';dateSelected=9;walkSeconds=0;walkRunning=false;clearInterval(walkInterval);go('home');toast('Demo reset.')};window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(screens.some(s=>s.id===id)&&id!==current){current=id;view='prototype';render()}});if(screens.some(s=>s.id===location.hash.slice(1)))current=location.hash.slice(1);
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'navigate_pet-care_screen',title:'Open Pet care design screen',description:'Navigate to a screen in the Pet care mobile design prototype. Does not perform real account or care actions.',inputSchema:{type:'object',properties:{screenId:{type:'string',enum:screens.map(s=>s.id)}},required:['screenId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.screenId!=='string'||!screens.some(s=>s.id===input.screenId))throw new Error('Unknown screen');go(input.screenId);return {screenId:current,title:screens.find(s=>s.id===current).title}}})}catch(e){}}
